import styles from "./countdown-unit.module.less";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { usePageVisibility } from "@/core/hooks/use-page-visibility";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import { useEffect, useState } from "react";
import { multipleClassNames } from "@/core/helpers";

type Props = {
  value: string;
  unit: "day" | "hour" | "minute" | "second";
  backgroundColor?: string;
  textColor?: string;
  lineColor?: string;
};
type CSSVariables = {
  [key: `--${string}`]: string | undefined;
};

const CountdownUnit = ({ value, unit, backgroundColor, textColor, lineColor }: Props) => {
  const style: React.CSSProperties & CSSVariables = {
    "--component-countdown-block-unit-background-color": backgroundColor,
    "--component-countdown-block-unit-text-color": textColor,
    "--component-countdown-block-unit-line-color": lineColor,
  };

  const { t } = useTranslation();
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const isVisible = usePageVisibility();

  const doAnimation = unit !== "second" && isVisible;

  if (!isMounted) {
    return <SkeletonRectangle className={multipleClassNames(styles.sizes, styles.skeleton)} />;
  }

  return (
    <div className={multipleClassNames(styles.sizes, styles.countdownUnit)} style={style}>
      <div className={styles.top}>
        <AnimatePresence initial={false}>
          <motion.p
            className={multipleClassNames("h1", styles.countNumber)}
            exit={doAnimation ? { top: "100%" } : undefined}
            initial={doAnimation ? { top: "-100%" } : undefined}
            animate={doAnimation ? { top: "0" } : undefined}
            transition={doAnimation ? { duration: 2 } : undefined}
            key={value}
          >
            {value}
          </motion.p>
        </AnimatePresence>
      </div>

      <span className={styles.breakLine}></span>
      <p className={styles.unitText}>{t(unit, { count: parseInt(value) })}</p>
    </div>
  );
};

export default CountdownUnit;
